{
  "themes": [
    {
      "name": "Queue and matchmaking wait times",
      "summary": "Players report long waits to enter matches, including long queues and too much time spent in the lobby or searching for a match. Some say friends quit over the delays.",
      "severity": "high",
      "comments": [
        {"id": "c029", "quote": "waited 17 mins to get in"},
        {"id": "c059", "quote": "Spent more time in the lobby than in the match"},
        {"id": "c080", "quote": "a third of it is watching the searching for match spinner"},
        {"id": "c091", "quote": "half an hour per game is rough"},
        {"id": "c089", "quote": "another 30 minute queue"}
      ]
    },
    {
      "name": "Slow progression and economy",
      "summary": "Players report that earning XP, shards, unlocks, and gear before ranked takes too long or feels repetitive. Progress feels slow for players with limited time.",
      "severity": "high",
      "comments": [
        {"id": "c065", "quote": "Progress is way too slow for people with jobs"},
        {"id": "c120", "quote": "XP per match is tiny"},
        {"id": "c002", "quote": "why is morrow locked behind 15000 shards when a win gives you 50"},
        {"id": "c030", "quote": "the grind to get the good gear before ranked is just boring"},
        {"id": "c011", "quote": "shards drop so slow"}
      ]
    },
    {
      "name": "Ability visibility and telegraphs",
      "summary": "Players report that ability effects, traps, and ultimate warnings are too faint or blend into the background. They cannot reliably see and react to dangerous effects.",
      "severity": "high",
      "comments": [
        {"id": "c042", "quote": "no visible edge"},
        {"id": "c117", "quote": "needs a bigger tell"},
        {"id": "c069", "quote": "ult warning is a small glow at the feet"},
        {"id": "c022", "quote": "spell effects blend in with the background way too much"},
        {"id": "c019", "quote": "all the ability vfx are so faint"},
        {"id": "c012", "quote": "Can't see half the ability effects"}
      ]
    },
    {
      "name": "Voice chat toxicity",
      "summary": "Players report frequent harassment, slurs, sexist comments, and screaming in voice chat. Some avoid voice chat entirely or mute everyone.",
      "severity": "high",
      "comments": [
        {"id": "c037", "quote": "my 15yo heard things on team chat"},
        {"id": "c100", "quote": "got called slurs in voice"},
        {"id": "c054", "quote": "As a woman I can't use voice chat in this game"},
        {"id": "c078", "quote": "hurling insults on voice"},
        {"id": "c096", "quote": "sexist comments on comms basically every other game"},
        {"id": "c114", "quote": "the mic toxicity is out of control"}
      ]
    },
    {
      "name": "Performance and stutters",
      "summary": "Players report low frame rates, FPS drops, and stutters during matches, even with capable hardware or reduced settings. The stutter can lead to deaths.",
      "severity": "high",
      "comments": [
        {"id": "c040", "quote": "drop to 40fps on Greywater when it rains"},
        {"id": "c107", "quote": "was 70 fps in the menu and 25 in the match"},
        {"id": "c055", "quote": "big stutter right as i respawn"}
      ]
    },
    {
      "name": "Bad spawns",
      "summary": "Players report spawning or being dropped in front of enemies or in dangerous positions. This leads to immediate deaths and repeated frustration.",
      "severity": "high",
      "comments": [
        {"id": "c105", "quote": "died 4 times before i took a single step"},
        {"id": "c032", "quote": "spawned right in front of their whole team and died in 2 seconds"},
        {"id": "c010", "quote": "spawning right in front of the enemy sniper"},
        {"id": "c008", "quote": "being dropped next to 3 enemies with full health while i have no abilities ready"}
      ]
    },
    {
      "name": "Tutorial and onboarding gaps",
      "summary": "Players report that onboarding and tutorial lessons rush through mechanics or fail to explain cooldowns, charge, ult use, and overcharge. Players finish without understanding key systems.",
      "severity": "medium",
      "comments": [
        {"id": "c088", "quote": "assumes you already played hero shooters"},
        {"id": "c013", "quote": "rushes thru like 10 mechanics in 3 mins"},
        {"id": "c036", "quote": "tutorial mentions it once in a popup that disappears before you can read it"},
        {"id": "c023", "quote": "not charged and theres no explanation how to charge it"}
      ]
    },
    {
      "name": "Confusing menus and UI",
      "summary": "Players report confusing menus, unlabeled icons, and hard to find options. Controller navigation and basic actions like inviting friends are difficult.",
      "severity": "medium",
      "comments": [
        {"id": "c057", "quote": "the cursor jumps around the menu in ways I can't predict"},
        {"id": "c041", "quote": "Half of them go to the same place"},
        {"id": "c066", "quote": "couldnt find keybinds for ages"},
        {"id": "c090", "quote": "no labels, just little shapes along the top"},
        {"id": "c077", "quote": "cant figure out how to invite a friend"}
      ]
    }
  ],
  "unassigned": [
    "c086",
    "c050"
  ]
}
